const FORUM_CATEGORIES=['Tümü','Oyun tavsiyeleri','Donanım','Oyun gündemi','Oyun kültürü','Yardım','Genel sohbet'];
let forumSearch='',forumCategory='Tümü',forumSort='activity',forumPageNumber=1;
let messages=read('messages',[]),blocks=read('blocks',{}),reports=read('reports',[]),campaigns=read('campaigns',[]);
let inboxPeer='PixelGezgin',adminTab='overview';
const commentState=new Map(),replyPages=new Map(),mediaURLs=new Map();
const isAdmin=()=>['owner','admin'].includes(user?.role);
const isOwner=()=>user?.role==='owner';
const canManageMember=a=>isAdmin()&&a&&a.nickname!==user.nickname&&a.role!=='owner'&&(isOwner()||a.role==='member');
const displayDate=ms=>new Date(ms).toLocaleString('tr-TR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Baghdad'});
const persistTopics=()=>write('topics',topics);
const canReadTopic=t=>!t.status||t.status==='published'||isAdmin()||t.author===user?.nickname;
const textNeedsReview=text=>(text.match(/https?:\/\//gi)||[]).length>2||/(.)\1{24}/u.test(text);
function saveSession(account){if(!memberAllowed(account)){toast("Bu üyelik erişime kapalı.");return;}user={nickname:account.nickname,email:account.email,role:account.role||'member'};write('user',user);closeModal();render()}
function bannerNotice(text){return `<div class="feature-notice">${icon('shield')}<span>${text}</span></div>`}
function pager(current,total,attribute,extra=''){
  const pages=Math.max(1,Math.ceil(total/5));return `<div class="pagination"><span>${total} kayıt · Sayfa ${current} / ${pages}</span><div><button ${attribute}="${current-1}" ${extra} ${current<=1?'disabled':''} aria-label="Önceki sayfa">← Önceki</button><button ${attribute}="${current+1}" ${extra} ${current>=pages?'disabled':''} aria-label="Sonraki sayfa">Sonraki →</button></div></div>`;
}
